import {KEY,STATES,uid,blank,question,example,validateVisit,readStore,summary,backup,restore} from './model.mjs';
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=blank(),screen='prepare',store={version:1,revision:0,visits:[]},enabled=false,dirty=false,conflict=false,damaged=false,queue=Promise.resolve(),size=32,lastFocus=null;
let selected=new Set(),noteSelection=new Set(),requestSelection=new Set();
let generation=0,editVersion=0,summaryStarted=false;
const notify=text=>{$('#notice').textContent=text;};
function status(text){$('#status').textContent=text||(conflict?'Not saved: another tab changed saved visits. Download your draft before reloading.':damaged?'Saved data could not be read. Your new draft is temporary.':!enabled?'Temporary visit — not saved. Save or download before closing.':dirty?'Changes not saved.': 'Saved on this device. Changes save automatically.');}
function load(){try{store=readStore(localStorage.getItem(KEY));damaged=false;}catch(e){damaged=true;notify(e.message+' Existing data has not been replaced.');}$('#repair').hidden=!damaged;status();renderList();}
function renderList(){$('#visit-list').innerHTML=store.visits.map(v=>`<button data-open="${esc(v.id)}">${esc(v.title||'Untitled visit')} ${esc(v.date)}</button>`).join('')||'<p>No saved visits.</p>';}
async function write(operation,{valid=()=>true,settled=()=>{dirty=false;}}={}){
 if(!navigator.locks){notify('Safe saving is unavailable in this browser. Use a full backup instead.');return false;}
 if(damaged||conflict){status();return false;}
 try{return await navigator.locks.request(KEY,async()=>{
  if(!valid())return false;
  const latest=readStore(localStorage.getItem(KEY));if(latest.revision!==store.revision){conflict=true;status();return false;}
  const next=operation(structuredClone(latest));next.revision=latest.revision+1;
  localStorage.setItem(KEY,JSON.stringify(next));store=next;settled();status();renderList();return true;
 });}catch(e){dirty=true;status('Not saved: storage is unavailable or damaged. Download a full backup.');notify(e.message);return false;}
}
function persist(){
 const requestedGeneration=generation,requestedEdit=editVersion,snapshot=validateVisit(visit);
 const valid=()=>enabled&&generation===requestedGeneration;
 queue=queue.then(async()=>{if(!valid())return;await write(s=>{const i=s.visits.findIndex(x=>x.id===snapshot.id);if(i<0)s.visits.push(snapshot);else s.visits[i]=snapshot;return s;},{valid,settled:()=>{dirty=editVersion!==requestedEdit;}});});return queue;
}
function changed(){editVersion++;dirty=true;status();if(enabled)persist();}
function current(){return visit.questions.find(q=>q.id===visit.current)||visit.questions[0];}
function field(label,body){return `<label>${label}${body.replace(/<(input|textarea|select)\b/,`<$1 aria-label="${esc(label)}"`)}</label>`;}
function stateSelect(q){return field('Question state',`<select data-q="${esc(q.id)}" data-field="state">${STATES.map(s=>`<option ${s===q.state?'selected':''}>${s}</option>`).join('')}</select>`);}
function editor(q,i){return `<article class="question">${field(`Question ${i+1}`,`<textarea dir="auto" data-q="${esc(q.id)}" data-field="text">${esc(q.text)}</textarea>`)}<button data-move="${esc(q.id)}" data-dir="-1" ${i===0?'disabled':''}>Move up</button><button data-move="${esc(q.id)}" data-dir="1" ${i===visit.questions.length-1?'disabled':''}>Move down</button><button data-remove="${esc(q.id)}">Remove question ${i+1}</button></article>`;}
function go(next){if(next==='during'&&!visit.questions.some(q=>q.text.trim())){notify('Add a question before starting the visit.');return;}screen=next;if(next==='review'&&!summaryStarted){selected=new Set(visit.questions.filter(q=>q.text.trim()).map(q=>q.id));noteSelection=new Set();requestSelection=new Set();summaryStarted=true;}render();$('#screen h2')?.focus();}
function render(){
 const active=document.activeElement;
 const focusKey=active?.dataset.q&&active?.dataset.field?`[data-q="${CSS.escape(active.dataset.q)}"][data-field="${CSS.escape(active.dataset.field)}"]`:null;
 $('#screen').innerHTML=screen==='prepare'?`<section><h2 tabindex="-1">Prepare my visit</h2><div class="row">${field('Visit title (optional)',`<input data-visit="title" value="${esc(visit.title)}">`)}${field('Date (optional)',`<input type="date" data-visit="date" value="${esc(visit.date)}">`)}</div>${visit.questions.map(editor).join('')}<button data-action="add">Add question</button><details class="private"><summary>Private preparation notes</summary><p>These never appear in the conversation display or shared summaries. Full backups include them.</p>${field('Private notes',`<textarea data-visit="privateNotes">${esc(visit.privateNotes)}</textarea>`)}</details><button data-screen="requests">Choose what helps</button><button class="primary" data-screen="during">Start the visit</button></section>`:
 screen==='requests'?`<section><h2 tabindex="-1">What helps me communicate</h2><p>Choose your own words. This step is optional.</p><button data-action="templates">Add editable examples</button>${visit.requests.map((r,i)=>`<article>${field('Request',`<textarea data-request="${i}">${esc(r.text)}</textarea>`)}${field(`<input type="checkbox" data-visible="${i}" ${r.visible?'checked':''}> Show this request`,'')}<button data-remove-request="${i}">Remove request</button></article>`).join('')}<button data-action="request">Add my own request</button><button data-action="show-requests">Preview selected requests</button><button data-screen="during">Continue to the visit</button></section>`:
 screen==='during'?`<section><h2 tabindex="-1">During the visit</h2>${current()?`<p>${esc(current().state)} · Question ${visit.questions.indexOf(current())+1} of ${visit.questions.length}</p><div class="big-question" dir="auto" style="--question-size:${size}px">${esc(current().text)}</div>${field('Question text size',`<select id="size"><option value="26" ${size===26?'selected':''}>Large</option><option value="32" ${size===32?'selected':''}>Larger</option><option value="42" ${size===42?'selected':''}>Largest</option></select>`)}<button data-action="previous">Previous</button><button data-action="next">Next</button>${stateSelect(current())}<details class="private"><summary>My personal answer note</summary><p>This is your note, not a confirmed clinical answer. It stays hidden when this section is closed.</p>${field('Answer note',`<textarea data-q="${esc(current().id)}" data-field="note">${esc(current().note)}</textarea>`)}</details><button data-action="show-note">Show this answer note</button>`:''}<button data-action="show-requests">Show what helps</button><details><summary>All questions — jump to one</summary>${visit.questions.map((q,i)=>`<button data-jump="${esc(q.id)}">${i+1}. ${esc(q.text||'(empty question)')} — ${esc(q.state)}</button>`).join('')}</details><button data-action="add-during">Add question during visit</button><button data-screen="prepare">Return to preparation</button><button data-action="pause">Pause this visit</button><button class="primary" data-screen="review">Review after the visit</button></section>`:
 `<section><h2 tabindex="-1">After the visit</h2><p>Choose questions to share. Include personal answer notes only if you want them in the summary.</p>${STATES.map(s=>`<h3>${s}</h3>${visit.questions.filter(q=>q.state===s).map(q=>`<article>${field(`<input type="checkbox" data-share="${esc(q.id)}" ${selected.has(q.id)?'checked':''}> Include this question`,'')}${field('Question',`<textarea data-q="${esc(q.id)}" data-field="text">${esc(q.text)}</textarea>`)}${stateSelect(q)}${field('My personal answer note (not confirmed by a clinician)',`<textarea data-q="${esc(q.id)}" data-field="note">${esc(q.note)}</textarea>`)}${field(`<input type="checkbox" data-share-note="${esc(q.id)}" ${noteSelection.has(q.id)?'checked':''}> Include this answer note`,'')}</article>`).join('')||'<p>No questions in this group.</p>'}`).join('')}<button data-action="add-during">Add follow-up question</button><h3>Communication requests to include</h3>${visit.requests.map((r,i)=>r.visible?field(`<input type="checkbox" data-share-request="${i}" ${requestSelection.has(i)?'checked':''}> ${esc(r.text)}`,''):'').join('')}<button class="primary" data-action="summary">Preview selected summary</button><button data-action="new">Start a new visit</button></section>`;
 document.querySelectorAll('nav button').forEach(b=>b.setAttribute('aria-current',b.dataset.screen===screen?'step':'false'));
 if(focusKey)document.querySelector(focusKey)?.focus();
}
function modal(title,content,actions=[]){lastFocus=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-body').replaceChildren();if(typeof content==='string'){const p=document.createElement('p');p.textContent=content;$('#dialog-body').append(p);}else $('#dialog-body').append(content);$('#dialog-actions').replaceChildren();for(const [label,fn] of actions){const b=document.createElement('button');b.textContent=label;b.onclick=fn;$('#dialog-actions').append(b);}$('#dialog').showModal();}
function close(){$('#dialog').close();}
$('#cancel-dialog').onclick=close;$('#dialog').addEventListener('close',()=>{lastFocus?.isConnected&&lastFocus.focus();$('#dialog-body').replaceChildren();$('#dialog-actions').replaceChildren();});
const pre=text=>{const n=document.createElement('pre');n.textContent=text;return n;};
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function replacement(fn){if(dirty||(!enabled&&(visit.questions.length||visit.privateNotes||visit.title||visit.requests.length))){modal('Replace this open draft?','Unsaved work will be lost. Cancel to download a full backup first.',[['Replace open draft',()=>{close();fn();}]]);}else fn();}
function openVisit(v,isSaved=false){generation++;editVersion=0;summaryStarted=false;visit=structuredClone(v);enabled=isSaved;dirty=false;selected.clear();noteSelection.clear();requestSelection.clear();screen='prepare';notify('');status();render();}
function addQuestion(text){const q=question(text);visit.questions.push(q);if(!visit.current)visit.current=q.id;selected.add(q.id);changed();return q;}
function promptQuestion(){const wrap=document.createElement('label');wrap.textContent='New question';const input=document.createElement('textarea');input.id='new-question';wrap.append(input);modal('Add a question',wrap,[['Add this question',()=>{if(!input.value.trim()){input.setCustomValidity('Write a question first.');input.reportValidity();return;}input.setCustomValidity('');addQuestion(input.value);close();render();}]]);input.focus();}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.visit){visit[t.dataset.visit]=t.value;changed();}if(t.dataset.q&&t.dataset.field!=='state'){visit.questions.find(q=>q.id===t.dataset.q)[t.dataset.field]=t.value;changed();}if(t.dataset.request!==undefined){visit.requests[Number(t.dataset.request)].text=t.value;requestSelection.clear();changed();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.q&&t.dataset.field==='state'){visit.questions.find(q=>q.id===t.dataset.q).state=t.value;changed();render();}if(t.dataset.visible!==undefined){visit.requests[+t.dataset.visible].visible=t.checked;changed();}for(const [key,set] of [['share',selected],['shareNote',noteSelection],['shareRequest',requestSelection]])if(t.dataset[key]!==undefined){const value=key==='shareRequest'?+t.dataset[key]:t.dataset[key];t.checked?set.add(value):set.delete(value);}if(t.id==='size'){size=+t.value;$('.big-question').style.setProperty('--question-size',`${size}px`);}});
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.screen){go(d.screen);return;}
 if(d.open){replacement(()=>openVisit(store.visits.find(v=>v.id===d.open),true));return;}
 if(d.move){const i=visit.questions.findIndex(q=>q.id===d.move),j=i+Number(d.dir);if(j>=0&&j<visit.questions.length){[visit.questions[i],visit.questions[j]]=[visit.questions[j],visit.questions[i]];changed();render();}return;}
 if(d.remove){const q=visit.questions.find(q=>q.id===d.remove);modal('Remove this question?',q.text,[['Remove question',()=>{visit.questions=visit.questions.filter(x=>x.id!==q.id);if(visit.current===q.id)visit.current=visit.questions[0]?.id||null;changed();close();render();}]]);return;}
 if(d.removeRequest!==undefined){visit.requests.splice(+d.removeRequest,1);requestSelection.clear();changed();render();return;}
 if(d.jump){visit.current=d.jump;changed();render();return;}
 switch(d.action){
 case 'new':replacement(()=>openVisit(blank()));break;
 case 'example':replacement(()=>openVisit(example()));break;
 case 'add':addQuestion('');render();$('#screen article:last-of-type textarea')?.focus();break;
 case 'add-during':promptQuestion();break;
 case 'request':visit.requests.push({text:'',visible:true});changed();render();break;
 case 'templates':visit.requests.push(...['Please ask one question at a time.','Written answers help.','Please give me time.'].map(text=>({text,visible:true})));changed();render();break;
 case 'show-requests':modal('What helps me communicate',pre(visit.requests.filter(r=>r.visible&&r.text.trim()).map(r=>r.text).join('\n\n')||'No requests selected.'));break;
 case 'show-note':modal('My personal note — not confirmed by a clinician',pre(current()?.note||'No answer note yet.'));break;
 case 'previous':case 'next':{const i=visit.questions.indexOf(current());const q=visit.questions[i+(d.action==='next'?1:-1)];if(q){visit.current=q.id;changed();render();}break;}
 case 'save':modal('Save on this device?','This visit, including private notes, will stay in this browser until deleted or cleared by the browser. Changes will save automatically. Anyone using this browser may see it.',[['Save this visit',async()=>{close();enabled=true;dirty=true;await persist();status();}]]);break;
 case 'backup':{const text=backup(visit);modal('Full backup includes private notes','Keep this file for your own recovery. It includes all questions, answer notes, and private preparation notes.',[['Download private backup',()=>download('my-visit-backup.json',text,'application/json')]]);break;}
 case 'summary':{const text=summary(visit,selected,noteSelection,requestSelection);modal('This is the exact summary to share',pre(text),[['Download summary',()=>download('my-visit-summary.txt',text,'text/plain;charset=utf-8')],['Copy summary',async()=>{try{await navigator.clipboard.writeText(text);notify('Summary copied.');}catch{notify('Copy is unavailable. Download the summary instead.');}}],['Print summary',()=>{$('#print-output').textContent=text;window.print();}]]);break;}
 case 'pause':if(enabled)await persist();modal('Visit paused',enabled&&!dirty&&!conflict?'Your saved visit keeps this question. Reopen it from Saved visits.':'This draft is not safely saved. Cancel to save it or download a full backup before closing.');break;
 case 'delete':case 'clear':{const all=d.action==='clear',targetId=visit.id,targetGeneration=generation;modal(all?'Clear all saved visits?':'Delete this visit?',all?'This removes every saved visit in this browser and the open draft. Download any backups you need first.':'This removes this saved visit and the open draft. Copies already exported remain outside the app.',[['Delete permanently',async()=>{close();await queue;if(generation!==targetGeneration){notify('The open visit changed. Deletion was cancelled.');return;}const ok=await write(s=>{s.visits=all?[]:s.visits.filter(v=>v.id!==targetId);return s;},{valid:()=>generation===targetGeneration});if(ok)openVisit(blank());}]]);break;}
 case 'reload':replacement(()=>{conflict=false;load();if(!damaged)openVisit(blank());});break;
 case 'repair':{let raw;try{raw=localStorage.getItem(KEY);}catch{notify('Storage cannot be read. Keep a backup of your current draft; try another browser.');break;}modal('Recover from damaged storage','First download the unreadable data if you want to keep it. It may contain private notes. Reset removes that saved collection; the current open draft stays available.',[['Download unreadable data',()=>download('my-visit-damaged-data.txt',raw||'', 'text/plain')],['Reset damaged saved data',async()=>{if(!navigator.locks){notify('Safe reset is unavailable in this browser.');return;}try{await navigator.locks.request(KEY,()=>{if(localStorage.getItem(KEY)!==raw)throw Error('Saved data changed. Cancel and reload before trying again.');const empty={version:1,revision:Date.now(),visits:[]};localStorage.setItem(KEY,JSON.stringify(empty));store=empty;damaged=false;conflict=false;enabled=false;dirty=true;$('#repair').hidden=true;close();renderList();status();notify('Damaged saved data was cleared. Your open draft is temporary. Save it if needed.');});}catch(e){notify(e.message);}}]]);break;}
 }
});
$('#import').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('Backup exceeds the 10 MB import limit.');const v=restore(await file.text());modal('Restore this backup as a new draft?',`Visit: ${v.title||'Untitled visit'}. It may contain private notes. Existing saved visits will be preserved; the open draft will be replaced. Cancel to back up your draft first.`,[['Restore as new draft',()=>{close();v.id=uid();openVisit(v);notify('Restored as a temporary draft. Save if you want to keep it here.');}]]);}catch(error){notify(`Could not restore: ${error.message} Your current visit is unchanged.`);}});
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){conflict=true;status();}});
window.addEventListener('beforeunload',e=>{if(dirty||(!enabled&&(visit.questions.length||visit.privateNotes||visit.requests.length))){e.preventDefault();e.returnValue='';}});
window.addEventListener('afterprint',()=>{$('#print-output').textContent='';});
load();render();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(async reg=>{const watch=()=>{const w=reg.installing;$('#offline').textContent='Checking app files for offline use…';w?.addEventListener('statechange',()=>{if(w.state==='redundant')$('#offline').textContent='Offline update failed. Keep a backup and try again when connected.';if(w.state==='installed'&&navigator.serviceWorker.controller)$('#offline').textContent='An update is downloaded. Save your work and close all app tabs to use it. Your saved visits will stay here.';});};reg.addEventListener('updatefound',watch);if(reg.installing)watch();await navigator.serviceWorker.ready;$('#offline').textContent=reg.waiting?'An update is downloaded. Save your work and close all app tabs to use it.':'Offline app files are ready. Saved visits stay on this device.';}).catch(()=>{$('#offline').textContent='Offline setup unavailable. Keep this page open or return while connected.';});}else $('#offline').textContent='This browser cannot install the offline app. Keep this page open while using it.';
